]$programs$::jsonb) item;
DO $$ BEGIN
  IF (SELECT count(*) FROM subvocalization_settings)<>13 OR (SELECT count(DISTINCT id) FROM subvocalization_settings)<>13
    OR (SELECT count(*) FROM subvocalization_settings WHERE old_config<>'null'::jsonb)<>6
    OR (SELECT count(*) FROM subvocalization_content)<>39 OR (SELECT count(DISTINCT id) FROM subvocalization_content)<>39
    OR (SELECT count(*) FROM subvocalization_questions)<>195 OR (SELECT count(DISTINCT id) FROM subvocalization_questions)<>195
    OR (SELECT count(*) FROM subvocalization_programs)<>13 OR (SELECT count(DISTINCT id) FROM subvocalization_programs)<>13
    THEN RAISE EXCEPTION 'Subvocalization payload incomplete'; END IF;
  IF (SELECT count(*) FROM speed_reading.exercise_types WHERE name='SubvocalizationReduction'
    AND engine_type='subvocalization_reduction' AND is_active AND NOT is_deleted)<>1
    THEN RAISE EXCEPTION 'Active Subvocalization type missing or ambiguous'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_settings s LEFT JOIN speed_reading.exercises e ON e.id=s.id
    LEFT JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
    WHERE (s.old_config<>'null'::jsonb AND e.id IS NULL) OR (e.id IS NOT NULL AND
      (t.name IS DISTINCT FROM 'SubvocalizationReduction' OR e.target_age_group_id IS DISTINCT FROM s.age_id
       OR e.difficulty_level<>s.level OR NOT e.is_active OR e.is_deleted
       OR (e.configuration_json IS DISTINCT FROM s.config AND e.configuration_json IS DISTINCT FROM s.old_config)
       OR (e.title IS DISTINCT FROM s.title AND e.title IS DISTINCT FROM s.old_title))))
    THEN RAISE EXCEPTION 'Subvocalization catalog baseline changed'; END IF;
  IF EXISTS(SELECT 1 FROM speed_reading.exercises e JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
    WHERE t.name='SubvocalizationReduction' AND e.is_active AND NOT e.is_deleted
      AND e.target_age_group_id IN (SELECT age_id FROM subvocalization_settings)
      AND NOT EXISTS(SELECT 1 FROM subvocalization_settings s WHERE s.id=e.id))
    THEN RAISE EXCEPTION 'Unexpected age-specific Subvocalization entry'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_content c LEFT JOIN subvocalization_settings s ON s.id=c.exercise_id
    WHERE s.id IS NULL OR c.age_id IS DISTINCT FROM s.age_id OR c.level<>s.level
      OR cardinality(regexp_split_to_array(btrim(c.content), E'\\s+'))<>c.word_count
      OR c.word_count<(s.config->'engineConfig'->'content'->>'minWordCount')::int
      OR c.word_count>(s.config->'engineConfig'->'content'->>'maxWordCount')::int
      OR jsonb_array_length(c.questions)<>5)
    THEN RAISE EXCEPTION 'Subvocalization content band/question mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_settings s LEFT JOIN subvocalization_content c ON c.exercise_id=s.id
    GROUP BY s.id HAVING count(c.id)<>3 OR count(DISTINCT c.content)<>3)
    THEN RAISE EXCEPTION 'Subvocalization needs three distinct texts per age/level'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_questions q JOIN subvocalization_content c ON c.id=q.text_id
    WHERE q.type NOT BETWEEN 1 AND 3 OR q.bloom NOT BETWEEN 1 AND 6 OR q.answer NOT IN ('A','B','C','D')
      OR btrim(q.a)='' OR btrim(q.b)='' OR btrim(q.c)='' OR btrim(q.d)=''
      OR btrim(q.evidence)='' OR strpos(c.content,q.evidence)=0)
    THEN RAISE EXCEPTION 'Subvocalization question quality/evidence mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_content c JOIN speed_reading.reading_texts t ON t.id=c.id
    WHERE t.title IS DISTINCT FROM c.title OR t.content IS DISTINCT FROM c.content OR t.word_count<>c.word_count
      OR t.exercise_id IS DISTINCT FROM c.exercise_id OR t.target_age_group_id IS DISTINCT FROM c.age_id
      OR t.difficulty_level<>c.level OR NOT t.is_active OR t.is_deleted)
    THEN RAISE EXCEPTION 'Subvocalization text collision or later edit'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_questions q JOIN speed_reading.reading_questions r ON r.id=q.id
    WHERE r.reading_text_id<>q.text_id OR r.question_text IS DISTINCT FROM q.question_text
      OR r.correct_answer IS DISTINCT FROM q.answer OR r.option_a IS DISTINCT FROM q.a
      OR r.option_b IS DISTINCT FROM q.b OR r.option_c IS DISTINCT FROM q.c OR r.option_d IS DISTINCT FROM q.d
      OR r.explanation IS DISTINCT FROM q.explanation OR r.type<>q.type OR r.bloom_level<>q.bloom
      OR r.difficulty_level<>q.level OR r.order_index<>q.position OR r.is_deleted)
    THEN RAISE EXCEPTION 'Subvocalization question collision or later edit'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_programs g LEFT JOIN speed_reading.program_templates p ON p.id=g.id
    WHERE p.id IS NULL OR NOT p."IsActive" OR p."IsDeleted" OR p."IsAssessment"
      OR p."InitialDifficultyLevel"<>g.level OR p."TotalDays"<>28 OR p."TotalWeeks"<>4
      OR p."TargetAgeGroupConfigurationId" IS DISTINCT FROM g.age_id
      OR (p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.base_pattern
        AND p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.old_pattern AND p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.pattern))
    THEN RAISE EXCEPTION 'Subvocalization program baseline changed'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_programs g
    JOIN speed_reading.program_templates p ON p.id=g.id
    JOIN speed_reading.student_program_progress s ON s."ProgramTemplateId"=p.id
    WHERE p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.pattern
      AND s."IsActive" AND s."CompletedDate" IS NULL AND s."ScheduleJson" IS NULL)
    THEN RAISE EXCEPTION 'Subvocalization existing active program needs schedule snapshot'; END IF;
END $$;
INSERT INTO speed_reading.exercises(id,exercise_type_id,title,description,type_code,difficulty_level,
  configuration_json,target_age_group_id,creator_id,is_active,created_at,created_by,version,is_deleted)
SELECT s.id,t.id,s.title,'Hafif sesli sayı sayma ile kelime gruplarını takip edin; sonunda beş anlama sorusu. İç ses azalması ölçülmez.',
  'reading',s.level,s.config,s.age_id,seed.creator_id,true,now(),'subvocalization-v2',1,false
FROM subvocalization_settings s CROSS JOIN speed_reading.exercise_types t
CROSS JOIN LATERAL (SELECT e.creator_id FROM speed_reading.exercises e
  WHERE e.exercise_type_id=t.id AND e.is_active AND NOT e.is_deleted ORDER BY e.id LIMIT 1) seed
WHERE t.name='SubvocalizationReduction' AND s.old_config='null'::jsonb ON CONFLICT(id) DO NOTHING;
INSERT INTO speed_reading.reading_texts(id,title,content,word_count,category,difficulty_level,target_age_group_id,
  language,is_active,tags,recommended_min_level,recommended_max_level,average_comprehension_score,times_read,
  average_reading_time_seconds,exercise_id,created_at,created_by,version,is_deleted)
SELECT id,title,content,word_count,'subvocalization',level,age_id,'tr',true,'subvocalization-v2;original-selection',level,level,
  0,0,0,exercise_id,now(),'subvocalization-v2',1,false FROM subvocalization_content ON CONFLICT(id) DO NOTHING;
INSERT INTO speed_reading.reading_questions(id,reading_text_id,question_text,type,bloom_level,difficulty_level,
  explanation,option_a,option_b,option_c,option_d,correct_answer,order_index,created_at,created_by,is_deleted)
SELECT id,text_id,question_text,type,bloom,level,explanation,a,b,c,d,answer,position,now(),'subvocalization-v2',false
FROM subvocalization_questions ON CONFLICT(id) DO NOTHING;
UPDATE speed_reading.exercises e SET configuration_json=s.config,title=s.title,updated_at=now(),
  updated_by='subvocalization-v2',version=e.version+1 FROM subvocalization_settings s
WHERE e.id=s.id AND (e.configuration_json IS DISTINCT FROM s.config OR e.title IS DISTINCT FROM s.title);
DO $$ BEGIN
  IF (SELECT count(*) FROM subvocalization_settings s JOIN speed_reading.exercises e ON e.id=s.id
    WHERE e.configuration_json=s.config AND e.title=s.title AND e.is_active AND NOT e.is_deleted)<>13
    THEN RAISE EXCEPTION 'Subvocalization final catalog verification failed'; END IF;
  IF EXISTS(SELECT 1 FROM subvocalization_programs p
    CROSS JOIN LATERAL jsonb_each(p.pattern) week
    CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(week.value)='object' THEN week.value ELSE '{}'::jsonb END) day
    CROSS JOIN LATERAL jsonb_array_elements(day.value) task
    WHERE NOT EXISTS(SELECT 1 FROM speed_reading.exercises e JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
      WHERE t.name=task->>'type' AND e.difficulty_level=(task->>'difficulty')::int AND e.target_age_group_id=p.age_id
        AND e.is_active AND NOT e.is_deleted AND t.is_active AND NOT t.is_deleted))
    THEN RAISE EXCEPTION 'Subvocalization program has an unavailable exercise'; END IF;
END $$;
UPDATE speed_reading.program_templates p SET "WeeklyPatternJson"=g.pattern,
  updated_at=now(),updated_by='subvocalization-v2',version=p.version+1 FROM subvocalization_programs g
WHERE p.id=g.id AND p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.pattern;
COMMIT;
